// Generated by the PixelKit editor from Assets, and written again when they change: change them, not this file.
// It names each of the game's assets, as in Sprite(.slime), Tilemap(.level1) and Sound.play(.jump), so a typo,
// or an asset renamed or deleted, is an error where it's used.

import PixelKit

extension ImageName {
    static let coin = ImageName("coin")
    static let slime = ImageName("slime")
    static let tiles = ImageName("tiles")
}

extension MapName {
    static let level1 = MapName("level1")
}

extension ObjectName {
    static let coin = ObjectName("coin")
    static let player = ObjectName("player")
}

extension SoundName {
    static let coin = SoundName("coin")
    static let jump = SoundName("jump")
    static let theme = SoundName("theme")
}
